{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목 근거를 실제 개선 결정으로 연결할 수 있는지 확인한다. 질문의 초점은 신고 목록 조회 쿼리의 개선 방향을 정한 근거이다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회에 3.2초가 걸렸던 상황이다.",
          "task": "확인된 병목에 맞는 쿼리 개선 방향을 정해야 했다.",
          "action": "실행 계획과 조회 구조에서 확인한 사실을 근거로 인덱스 추가와 조인 정리를 선택한 판단을 설명한다.",
          "result": "확인한 병목과 선택한 개선 방향 사이의 연결이 구체적으로 드러난다. 개선 전후 측정 절차를 별도로 설명할 필요는 없다."
        },
        "expectedEvidence": [
          "쿼리 개선 방향을 정한 구체적인 근거",
          "실행 계획이나 조회 구조에서 실제로 확인한 병목 관련 사실",
          "확인한 병목에 인덱스 추가와 조인 정리가 적합하다고 판단한 연결 설명"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 시간을 3.2초에서 0.4초로 줄이셨던데요, 당시 쿼리 개선 방향은 무엇을 근거로 정하셨어요?",
      "answerTip": "당시 경험을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "개선 방향을 정한 근거를 실제 쿼리 상황에 맞춰 구체적으로 설명한다.",
            "실행 계획이나 조회 구조에서 확인한 병목 관련 사실이 명확하다.",
            "확인한 병목을 인덱스 추가와 조인 정리로 줄일 수 있다고 판단한 이유가 기술적으로 타당하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "개선 방향의 근거와 병목 관련 사실을 일부 제시하지만 구체성이 부족하다.",
            "병목과 선택한 개선 방법의 연결은 설명하지만 실제 조회 구조에 대한 설명이 제한적이다."
          ]
        },
        "poor": {
          "criteria": [
            "개선 방법이나 단축된 시간만 말하고 선택 근거를 제시하지 못한다.",
            "병목 관련 사실이 없거나 해당 사실과 개선 방법의 연결이 기술적으로 타당하지 않다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류의 원인에 맞는 복구 조치를 직접 적용할 수 있는지 확인한다. 질문의 초점은 알림 중복 발송을 막기 위해 실제 적용한 복구 조치이다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 알림이 중복 발송되었고 스케줄러가 서버 두 대에서 동시에 실행된 상황이다.",
          "task": "스케줄러 중복 실행으로 발생한 알림 중복 발송을 막는 복구 조치를 적용해야 했다.",
          "action": "본인이 적용한 잠금 조치와 해당 조치가 중복 실행을 제어하는 방식을 설명한다.",
          "result": "실제 적용한 복구 조치와 오류 원인의 연결이 구체적으로 드러난다. 재발 방지 절차나 별도의 효과 측정은 필수로 요구하지 않는다."
        },
        "expectedEvidence": [
          "알림 중복 발송 오류에 본인이 실제 적용한 구체적인 복구 조치",
          "서버 두 대에서 스케줄러가 동시에 실행되던 조건과 복구 조치의 연결",
          "적용한 잠금이 여러 서버의 중복 실행을 제어하는 방식"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 수정하셨던데요, 그때 실제로 적용한 서버 복구 조치는 무엇이었어요?",
      "answerTip": "본인이 했던 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "본인이 실제 적용한 복구 조치를 구체적으로 설명한다.",
            "서버 두 대의 스케줄러 동시 실행과 복구 조치의 관계가 명확하다.",
            "잠금이 여러 서버의 중복 실행을 제어하는 방식을 기술적으로 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "본인이 적용한 잠금 조치와 중복 실행 문제의 관계는 확인된다.",
            "잠금의 실제 적용 방식이나 여러 서버의 실행을 제어하는 설명은 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "원인이나 오류 현상만 말하고 실제 적용한 복구 조치를 제시하지 못한다.",
            "잠금을 사용했다는 언급에 그치거나 설명한 조치로는 여러 서버의 중복 실행을 제어할 수 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "요청을 실제 구현 범위로 구체화할 수 있는지 검증한다. 개발 담당 팀원과 범위를 조정했던 경험에서 구현할 내용과 제외할 내용을 정한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 인터뷰로 수집한 요청을 개발 담당 팀원과 조정하던 상황이다.",
          "task": "서비스가 해결할 문제를 바탕으로 당시 구현할 범위를 정해야 했다.",
          "action": "요청의 목적과 범위 제약을 근거로 구현에 포함하거나 제외할 내용을 판단한 설명이 나온다.",
          "result": "당시 정한 구현 범위와 그 판단 근거의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "당시 구현 범위를 정한 구체적인 근거",
          "판단의 바탕이 된 사용자 요청의 목적이나 범위 제약",
          "그 근거가 실제 포함하거나 제외한 내용으로 이어진 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 범위를 조정하셨던데요, 당시 구현 범위는 어떤 근거로 정하셨어요?",
      "answerTip": "당시의 구체적인 장면을 떠올려 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 범위를 정한 근거를 실제 사용자 요청의 목적이나 범위 제약에 기반해 구체적으로 설명한다.",
            "해당 근거가 어떤 내용을 포함하거나 제외하는 결정으로 이어졌는지 명확하게 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위를 정한 근거는 제시하지만 사용자 요청의 목적이나 범위 제약에 대한 설명이 추상적이다.",
            "포함하거나 제외한 내용은 드러나지만 판단 근거와의 연결이 일부 불명확하다."
          ]
        },
        "poor": {
          "criteria": [
            "구현 범위를 정한 근거를 설명하지 못하거나 범위 조정에 관한 일반론만 말한다.",
            "사용자 요청이나 범위 제약이 실제 포함·제외 결정과 연결되지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 구현 가능한 화면 동작으로 구체화할 수 있는지 검증한다. 화면설계서 작성 경험에서 예외 상황의 화면 동작을 정하며 고민한 결정 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스의 화면설계서에 예외 상황을 담던 상황이다.",
          "task": "해당 예외 상황에서 화면이 보여 줄 상태나 허용할 동작을 정해야 했다.",
          "action": "고민했던 화면 동작의 결정과 그 동작을 적용할 예외 조건, 그렇게 정한 이유를 설명한다.",
          "result": "예외 조건에 대응하는 화면 동작의 설계 결정이 구현 내용을 이해할 수 있는 수준으로 드러난다."
        },
        "expectedEvidence": [
          "예외 상황의 화면 동작에 관해 고민했던 구체적인 설계 결정",
          "그 화면 동작이 적용되는 예외 조건이나 화면 상태",
          "선택한 화면 동작이 해당 예외 상황에 적합하다고 판단한 이유"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨던데요, 예외 상황의 화면 동작에 관해 가장 고민하신 결정은 뭐였어요?",
      "answerTip": "기억에 남는 한 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "고민했던 설계 결정을 화면이 보여 줄 상태나 허용할 동작이 명확히 드러나도록 설명한다.",
            "화면 동작이 적용되는 예외 조건을 구체적으로 제시하고, 해당 동작을 선택한 이유를 그 조건과 타당하게 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황에 대한 설계 결정은 제시하지만 화면 상태나 동작의 구체성이 부족하다.",
            "적용 조건이나 선택 이유는 일부 설명하지만 화면 동작과의 연결이 충분히 명확하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "화면설계서 작성 사실이나 도구 사용만 설명하고 예외 상황의 화면 동작에 관한 결정을 제시하지 못한다.",
            "설명한 화면 동작의 적용 조건이나 선택 이유가 불분명해 해당 예외 상황과의 연결을 확인하기 어렵다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 그대로 수행하지 않고 투약을 보류할 수 있는지 확인한다. 평소와 다른 진통제 용량을 보고 투약 중단을 결정한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어온 상황이다.",
          "task": "해당 처방대로 투약을 진행해도 되는지 판단해야 했다.",
          "action": "처방 용량을 의심한 구체적인 근거를 설명하고, 확인되지 않은 처방의 투약을 보류한 이유를 밝힌다.",
          "result": "투약을 진행하지 않기로 한 판단과 그 근거의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "진통제 투약을 멈추기로 판단한 구체적인 근거",
          "처방 용량의 이상 여부를 판단하는 데 사용한 비교 기준이나 확인 사실",
          "확인되지 않은 용량으로 투약을 진행해서는 안 된다고 판단한 이유"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 처방 용량이 평소의 두 배로 들어온 적이 있으셨는데요, 투약을 멈추기로 판단한 근거는 무엇이었어요?",
      "answerTip": "당시 상황을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투약 중단의 근거를 실제 처방 내용과 비교 기준을 들어 구체적으로 설명한다.",
            "용량의 이상 여부가 확인되지 않은 상태에서 투약을 진행하지 않아야 한다는 판단을 명확하게 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 용량 때문에 투약을 멈췄다는 핵심 근거는 제시하지만, 비교 기준이나 확인 사실의 설명이 제한적이다.",
            "확인 전 투약 보류의 필요성은 설명하지만, 해당 처방에서 보류를 결정한 이유가 다소 포괄적이다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 구체적인 근거를 설명하지 못하거나 처방 용량을 의심한 사실과 연결하지 못한다.",
            "용량이 의심스러워도 확인 없이 투약을 진행할 수 있다는 판단을 보인다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태 변화를 간호 기록으로 남기는 판단을 확인한다. 활력징후와 통증 관찰 업무에서 기록할 변화를 정한 기준에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동에서 환자의 활력징후와 통증을 관찰하고 기록한 업무 상황이다.",
          "task": "관찰한 환자 상태 변화를 간호 기록에 남겨야 했다.",
          "action": "기록할 상태 변화를 정한 기준을 실제 관찰 내용과 연결하여 설명한다.",
          "result": "어떤 상태 변화를 어떤 근거로 기록했는지가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "관찰한 환자 상태 변화를 간호 기록에 남긴 판단 기준",
          "그 기준을 적용한 실제 활력징후 또는 통증 변화와 비교 기준",
          "해당 관찰 내용이 기록에 필요하다고 판단한 이유"
